import Foundation

/// Parity check of ios/PrismCore against fixtures generated by the TypeScript
/// engine (PRiSM `bun scripts/swift-core-fixtures.ts <dir>`). Every fixture is
/// decoded, run through the Swift engine, encoded to JSON and compared
/// structurally with what TypeScript produced (numbers within 1e-9, key order
/// irrelevant, an absent key differs from a null one). Exits non-zero on any mismatch.
@main struct PrismCoreCheck {
  static func main() throws {
    let arguments = CommandLine.arguments
    let fixtureDir = URL(fileURLWithPath: arguments.count > 1 ? arguments[1] : "test/native/fixtures/prism-core")
    let diffDir = URL(fileURLWithPath: ProcessInfo.processInfo.environment["PRISM_CORE_DIFF_DIR"]
      ?? (NSTemporaryDirectory() as NSString).appendingPathComponent("prism-core-check-diffs"))
    try? FileManager.default.removeItem(at: diffDir)
    let files = try FileManager.default.contentsOfDirectory(at: fixtureDir, includingPropertiesForKeys: nil)
      .filter { $0.pathExtension == "json" }
      .sorted { $0.lastPathComponent < $1.lastPathComponent }
    guard !files.isEmpty else {
      print("No fixtures in \(fixtureDir.path)")
      exit(1)
    }
    var failures = 0
    var counts: [String: Int] = [:]
    for file in files {
      let fixture = try JSONSerialization.jsonObject(with: Data(contentsOf: file)) as! [String: Any]
      let name = fixture["name"] as? String ?? file.deletingPathExtension().lastPathComponent
      let kind = fixture["kind"] as! String
      counts[kind, default: 0] += 1
      var problems: [String] = []
      var actual: Any = NSNull()
      do {
        let outcome = try run(kind: kind, input: fixture["input"] as! [String: Any])
        actual = outcome.value
        problems += outcome.problems
        if let expectedError = fixture["expectedError"] as? [String: Any] {
          let got = outcome.error.map { ["code": $0.code, "message": $0.message] as [String: Any] } ?? [:]
          problems += compare(expectedError, got, "$error")
          if let expected = fixture["expected"] { problems += compare(expected, actual, "$") }
        } else if let error = outcome.error {
          problems.append("$: unexpected error \(error)")
        } else {
          problems += compare(fixture["expected"] ?? NSNull(), actual, "$")
        }
      } catch {
        problems.append("$: \(error)")
      }
      if problems.isEmpty { continue }
      failures += 1
      try FileManager.default.createDirectory(at: diffDir, withIntermediateDirectories: true)
      let actualURL = diffDir.appendingPathComponent("\(name).actual.json")
      let diffURL = diffDir.appendingPathComponent("\(name).diff.txt")
      try JSONSerialization.data(withJSONObject: actual, options: [.prettyPrinted, .sortedKeys, .fragmentsAllowed]).write(to: actualURL)
      try problems.joined(separator: "\n").write(to: diffURL, atomically: true, encoding: .utf8)
      print("FAIL \(name): \(problems.count) difference(s), first: \(problems[0])\n     diff: \(diffURL.path)\n     actual: \(actualURL.path)")
    }
    try checkLegacyTimelineDecoding()
    let summary = counts.sorted { $0.key < $1.key }.map { "\($0.value) \($0.key)" }.joined(separator: ", ")
    if failures > 0 {
      print("PrismCore parity: \(failures) of \(files.count) fixtures failed (\(summary)).")
      exit(1)
    }
    print("PrismCore parity: all \(files.count) fixtures match TypeScript (\(summary)).")
  }

  struct Outcome {
    var value: Any
    var error: PrismDomainError?
    var problems: [String] = []
  }

  static func run(kind: String, input: [String: Any]) throws -> Outcome {
    switch kind {
    case "preview":
      let snapshot = try JSONDecoder().decode(PrismBillingSnapshot.self, from: data(input["snapshot"]!))
      do {
        let preview = try PrismCheckoutEngine.preview(snapshot: snapshot, playerId: input["playerId"] as! String)
        let view = try preview.viewOrThrow()
        var problems: [String] = []
        if view != preview.view() { problems.append("$: view() differs from viewOrThrow()") }
        // The preview's timeline equals the standalone builder over its bill inputs.
        if try prismBuildBillTimelineOrThrow(preview.billInputs) != view.timeline { problems.append("$.timeline: billInputs rebuild differs") }
        let encoded = try json(view)
        // The view's timeline survives a decode/encode round trip unchanged (receipts carry it).
        let timelineJSON = (encoded as! [String: Any])["timeline"]!
        let reencoded = try json(try JSONDecoder().decode(PrismBillTimeline.self, from: data(timelineJSON)))
        problems += compare(timelineJSON, reencoded, "$.timeline(roundtrip)")
        return Outcome(value: encoded, error: nil, problems: problems)
      } catch let error as PrismDomainError {
        return Outcome(value: NSNull(), error: error)
      }
    case "timeline":
      let inputs = try JSONDecoder().decode(PrismBillInputs.self, from: data(input["billInputs"]!))
      let timeline = try prismBuildBillTimelineOrThrow(inputs, timeZone: input["timeZone"] as? String)
      var problems: [String] = []
      if prismBuildBillTimeline(inputs, timeZone: input["timeZone"] as? String) != timeline { problems.append("$: non-throwing builder differs") }
      return Outcome(value: try json(timeline), error: nil, problems: problems)
    case "segments":
      let config = try JSONDecoder().decode(PrismPricingConfig.self, from: data(input["config"]!))
      let localDate = input["localDate"] as! String, zone = input["displayTimeZone"] as! String
      let segments = PrismDaySegments.segments(config: config, localDate: localDate, displayTimeZone: zone)
      do {
        let thrown = try PrismDaySegments.segmentsOrThrow(config: config, localDate: localDate, displayTimeZone: zone)
        let problems = thrown == segments ? [] : ["$: segments() differs from segmentsOrThrow()"]
        return Outcome(value: try json(segments), error: nil, problems: problems)
      } catch let error as PrismDomainError {
        return Outcome(value: try json(segments), error: error)
      }
    default:
      throw PrismDomainError("Unknown fixture kind \(kind)", "CHECK")
    }
  }

  /// Receipts from older servers: missing new fields, legacy keys, numeric `capped` on entries.
  static func checkLegacyTimelineDecoding() throws {
    let legacy = #"{"totals":[{"name":"台球","amount":12}],"shares":[{"x":1}],"tracks":[{"id":"s:p","name":"台球","lane":0,"color":0,"startedAt":"2026-09-13T10:00:00.000Z","endedAt":"2026-09-13T11:00:00.000Z"}],"events":[{"at":"2026-09-13T11:00:00.000Z","time":"11:00","date":"2026-09-13","entries":[{"trackId":"s:p","kind":"end","name":"台球","rule":"日间","amount":12,"capped":0,"unitsFrom":3,"periodLabel":"10:00 – 11:00","startedAt":"2026-09-13T10:00:00.000Z","endedAt":"2026-09-13T11:00:00.000Z"}]}]}"#
    let timeline = try JSONDecoder().decode(PrismBillTimeline.self, from: Data(legacy.utf8))
    precondition(timeline.tracks[0].capped == nil && timeline.events[0].entries[0].capped == nil)
    precondition(timeline.events[0].entries[0].amount == 12 && timeline.events[0].entries[0].unitFills == nil)
  }

  static func data(_ object: Any) throws -> Data {
    try JSONSerialization.data(withJSONObject: object, options: [.fragmentsAllowed])
  }

  static func json<T: Encodable>(_ value: T) throws -> Any {
    try JSONSerialization.jsonObject(with: JSONEncoder().encode(value), options: [.fragmentsAllowed])
  }

  static func isBool(_ value: Any) -> Bool {
    guard let number = value as? NSNumber else { return false }
    return CFGetTypeID(number) == CFBooleanGetTypeID()
  }

  static func compare(_ expected: Any, _ actual: Any, _ path: String) -> [String] {
    switch (expected, actual) {
    case (is NSNull, is NSNull):
      return []
    case (let e as NSNumber, let a as NSNumber):
      if isBool(e) || isBool(a) {
        return isBool(e) && isBool(a) && e.boolValue == a.boolValue ? [] : ["\(path): expected \(e) got \(a)"]
      }
      return abs(e.doubleValue - a.doubleValue) <= 1e-9 ? [] : ["\(path): expected \(e) got \(a)"]
    case (let e as String, let a as String):
      return e == a ? [] : ["\(path): expected \"\(e)\" got \"\(a)\""]
    case (let e as [Any], let a as [Any]):
      if e.count != a.count { return ["\(path): expected \(e.count) items got \(a.count)"] }
      return zip(e, a).enumerated().flatMap { compare($0.element.0, $0.element.1, "\(path)[\($0.offset)]") }
    case (let e as [String: Any], let a as [String: Any]):
      var problems: [String] = []
      for key in Set(e.keys).union(a.keys).sorted() {
        switch (e[key], a[key]) {
        case (nil, .some): problems.append("\(path).\(key): unexpected key")
        case (.some, nil): problems.append("\(path).\(key): missing key")
        case (let ev?, let av?): problems += compare(ev, av, "\(path).\(key)")
        default: break
        }
      }
      return problems
    default:
      return ["\(path): expected \(expected) got \(actual)"]
    }
  }
}
